# -*- coding: utf-8 -*-
# Instructivo de la aplicación Android. Mismos tipos de bloque que el instructivo del portal.
CH = []
def ch(title, *blocks): CH.append((title, list(blocks)))

ch("Qué es esta aplicación",
 ("p", "<b>OPEN SOURCE PARIZ</b> es una aplicación para teléfonos y tablets con Android que maneja un módulo de radio <b>LoRa Mesh</b>. Con ella podés escribir y recibir mensajes por radio, ver a los demás nodos en una lista y en un mapa, configurar el equipo, pedir telemetría y, cuando hay Internet, sumar servidores MQTT."),
 ("p", "Es la misma herramienta que el portal de la computadora, adaptada al celular. No hace falta la PC: el teléfono se conecta directo al nodo por <b>Bluetooth</b>, por <b>cable USB</b> (con adaptador OTG) o por <b>WiFi</b>."),
 ("h3", "Lo principal que vas a poder hacer"),
 ("ul", ["Mandar mensajes a un canal o a un nodo puntual, con reintentos automáticos si no sale a la primera.",
         "Responder citando un mensaje y reaccionar con emojis.",
         "Ver el mapa con los nodos, su altura y su estado, y <b>guardar zonas del mapa para usarlas sin señal</b>.",
         "Ver la topología: quién se escucha con quién y quién depende de repetidores.",
         "Recibir <b>avisos del celular</b> aunque la app esté en segundo plano o la pantalla apagada.",
         "Pasarle al nodo la <b>ubicación del GPS del teléfono</b> si el nodo no tiene GPS propio.",
         "Compartir los canales con un <b>código QR</b> y leer el de otro equipo con la cámara.",
         "Usar el botón rojo de <b>EMERGENCIAS</b>, que manda la misma alerta a todos los canales.",
         "Llevar el libro de guardia y exportarlo a PDF o Excel desde el propio teléfono."]),
 ("warn", "<b>Seguridad.</b> El botón de EMERGENCIAS manda un mensaje por radio LoRa: llega solamente si hay otro nodo o un repetidor al alcance. <b>No reemplaza</b> a los servicios de emergencia (911 / 105 / 100). Probá siempre el sistema antes de depender de él."),
)

ch("Instalar la aplicación",
 ("table", ["Requisito", "Detalle"], [
   ["Android", "7.0 o más nuevo."],
   ["Nodo LoRa Mesh", "Un módulo con firmware 2.x. Se probó contra Heltec V3 con firmware 2.8."],
   ["Archivo", "<b>OPEN-SOURCE-PARIZ-app-1.6.apk</b>. No está en Google Play: se instala desde el archivo."],
   ["Para cable USB", "Un adaptador <b>OTG</b> y un cable de datos (muchos cables son solo de carga)."]]),
 ("h3", "Pasos"),
 ("steps", [
   "Copiá el archivo <b>.apk</b> al celular: por cable, mandándotelo por WhatsApp a vos mismo, o bajándolo de la carpeta de Drive.",
   "Abrilo desde <b>Archivos</b> o desde la notificación de la descarga.",
   "Android avisa que la instalación desde esta fuente está bloqueada: tocá <b>Configuración</b>, activá <b>Permitir de esta fuente</b> y volvé atrás.",
   "Tocá <b>Instalar</b>. Si Play Protect muestra «app no verificada», tocá <b>Más detalles → Instalar de todas formas</b>: aparece porque la app no se publicó en la tienda, no porque tenga algo raro.",
   "Abrí la app."]),
 ("h3", "Actualizar a una versión nueva"),
 ("p", "Instalá la APK nueva encima de la anterior: los mensajes, los nodos y los ajustes se conservan. Funciona porque todas las versiones van firmadas con la misma <b>clave de firma</b>. Esa clave se entrega aparte y hay que guardarla en un lugar seguro: si se pierde, las versiones futuras ya no se van a poder instalar encima y vas a tener que desinstalar, perdiendo lo guardado en el teléfono."),
 ("note", "Para saber qué versión tenés abierta, mirá en el menú lateral, en <b>Versión del software</b>: dice <b>Portal: 1.3 (app)</b> y la fecha."),
)

ch("Permisos que pide y para qué",
 ("p", "La app pide los permisos de a uno, recién cuando hacen falta. Ninguno se usa para otra cosa que lo que dice acá."),
 ("table", ["Permiso", "Cuándo lo pide", "Para qué"], [
   ["Dispositivos cercanos", "La primera vez que tocás <b>Bluetooth</b>", "Encontrar el nodo y conectarse. En Android 11 o anterior, en vez de este permiso pide <b>Ubicación</b>, porque esas versiones la exigen para buscar equipos Bluetooth."],
   ["Notificaciones", "Al abrir la app por primera vez", "Mostrar los avisos de mensajes y alertas, y la notificación fija de estado."],
   ["Ubicación", "Solo si activás el GPS del celular", "Tomar tu posición y pasársela al nodo."],
   ["Cámara", "Solo si tocás <b>Escanear QR</b>", "Leer el código QR de canales de otro equipo."],
   ["Almacenamiento", "Solo en Android 9 o anterior, al exportar", "Guardar los archivos en Descargas."]]),
 ("note", "Si rechazaste un permiso y querés darlo después, entrá en <b>Ajustes del teléfono → Apps → OPEN SOURCE PARIZ → Permisos</b>."),
)

ch("Conectar el nodo",
 ("fig", "a01_conectar", "Pantalla de inicio: las tres formas de conectar el nodo", []),
 ("h3", "Por Bluetooth"),
 ("steps", ["Activá el Bluetooth del teléfono y el del nodo (en el nodo: Configuración del dispositivo → Bluetooth).",
            "Desconectá el nodo de cualquier otro celular: atiende a uno por vez.",
            "En la app tocá <b>Bluetooth</b>. Aparece la lista de equipos cercanos con su intensidad de señal.",
            "Elegí el tuyo. Si pide emparejar, poné el PIN que muestra la pantalla del nodo; si el nodo no tiene pantalla, suele ser <b>123456</b>.",
            "Si tu nodo no aparece, tocá <b>Mostrar todos</b>: incluye equipos que no se anuncian como nodo."]),
 ("h3", "Por cable USB"),
 ("steps", ["Enchufá el nodo al teléfono con un adaptador <b>OTG</b> y un cable de datos.",
            "Android pregunta si abre OPEN SOURCE PARIZ: tocá <b>Aceptar</b> (podés marcar «usar siempre»).",
            "Si no preguntó nada, abrí la app y tocá <b>USB (cable)</b>."]),
 ("p", "Funcionan los chips más comunes de los nodos: <b>CP210x</b>, <b>CH340/CH9102</b> y el USB nativo de ESP32-S3 y nRF52 (RAK4631). Los adaptadores FTDI todavía no están soportados."),
 ("h3", "Por WiFi"),
 ("steps", ["El nodo tiene que tener el WiFi encendido y el servidor web activo, y estar en la misma red que el teléfono (o que el teléfono esté conectado al punto de acceso del propio nodo).",
            "Tocá <b>Red (WiFi / LAN)</b> y escribí la dirección IP del nodo, por ejemplo <b>192.168.1.10</b>.",
            "Si no sabés la IP, usá <b>Buscar nodos en la red</b>: poné los <b>tres primeros números</b> de tu red (por ejemplo <b>192.168.1</b>) y tocá buscar.",
            "Tocá <b>Probar conexión</b> para confirmar y después <b>Guardar y conectar</b>."]),
 ("tip", "En la app, la búsqueda de nodos la hace <b>Android, no el visor web</b>: prueba los puertos de verdad, así que es bastante más rápida y confiable que en la computadora. También acepta certificados propios del nodo en direcciones de red privada, sin que tengas que aceptarlos a mano."),
 ("note", "Las conexiones quedan guardadas: la próxima vez entrás con un toque desde la pantalla de inicio."),
)

ch("Cómo se maneja en el celular",
 ("fig", "a02_mensajes", "Pantalla de mensajes con la barra inferior siempre a mano", []),
 ("ul", ["<b>Barra inferior:</b> abajo están siempre <b>Mensajes, Mapa, Topología y Nodos</b>. <b>Más</b> abre el menú completo.",
         "<b>Menú lateral:</b> se abre con <b>Más</b> o con el botón <b>☰</b> de arriba a la izquierda. Tiene Ajustes, Configuración del nodo, los canales y las herramientas.",
         "<b>Bloques plegables:</b> dentro del menú, los títulos <b>Herramientas</b>, <b>Estado del módulo</b>, <b>Versión del software</b> y <b>Apariencia</b> se contraen tocándolos. Sirve para que entre todo en pantallas chicas; el teléfono se acuerda de cómo los dejaste.",
         "<b>Botón atrás:</b> manda la app al fondo sin desconectar. Para cerrarla del todo, usá <b>Cerrar la app</b> en la notificación fija."]),
 ("fig", "a08_menu", "Menú lateral con los bloques plegables", []),
)

ch("Mensajes",
 ("p", "Elegí el canal en la barra de arriba o un nodo en la lista para mandarle un mensaje privado. Escribí abajo y tocá <b>Enviar</b>. Cada mensaje muestra la hora y si salió."),
 ("h3", "Responder y reaccionar"),
 ("fig", "a03_menu_mensaje", "Menú de un mensaje: reacciones y acciones", []),
 ("ul", ["Tocá el botón <b>⋯</b> de un mensaje para abrir el menú.",
         "<b>Reaccionar:</b> tocá un emoji. Queda pegado abajo del mensaje original, no sale como mensaje aparte.",
         "<b>Responder:</b> arriba del teclado aparece «Respondiendo a…»; escribí y enviá. Tu mensaje sale con la cita del original.",
         "<b>Responder en privado:</b> abre un mensaje directo al autor.",
         "<b>Copiar texto</b> y <b>Ver detalle del nodo</b> completan el menú."]),
 ("note", "Las respuestas y las reacciones viajan con el formato estándar de la red, así que también se ven en las demás aplicaciones LoRa Mesh."),
 ("h3", "Si un mensaje no sale"),
 ("p", "El portal reintenta solo: a los 60 segundos y otra vez a los 60. Si aun así no se entrega, queda marcado como <b>NO ENTREGADO</b> con un botón <b>Reenviar mensaje</b>. Un mensaje a un canal se da por enviado cuando el nodo lo transmite; uno privado espera la confirmación del destinatario."),
)

ch("Avisos del celular",
 ("p", "Con la app en segundo plano o la pantalla apagada, los mensajes llegan como notificaciones de Android. Al tocarlas se abre esa conversación."),
 ("fig", "a10_sonidos", "Ajustes de sonidos y avisos", []),
 ("ul", ["Hay <b>tres tipos</b>, que Android maneja por separado: <i>Mensajes de canales</i>, <i>Mensajes directos y favoritos</i> (con vibración) y <i>Alertas de emergencia</i>.",
         "Las <b>alertas de emergencia</b> usan el sonido de <b>alarma</b> del teléfono y suenan aunque tengas No molestar activado.",
         "Los avisos de una misma conversación se agrupan: no te llena la barra de notificaciones.",
         "En <b>Ajustes → Sonidos y notificaciones</b> podés apagarlos, o dejar solo los directos y las alertas.",
         "Los canales silenciados y el silencio nocturno también valen para los avisos. Las alertas de emergencia avisan siempre."]),
 ("tip", "Para que Android no corte la conexión con la pantalla apagada, entrá en <b>Ajustes del teléfono → Apps → OPEN SOURCE PARIZ → Batería</b> y elegí <b>Sin restricciones</b>. Es el ajuste que más cambia la experiencia."),
 ("note", "Mientras la app está abierta queda una <b>notificación fija</b> con el estado de la conexión. Es la que mantiene vivo el proceso para que sigas recibiendo con la pantalla apagada."),
)

ch("Nodos y ficha de cada nodo",
 ("fig", "a07_nodos", "Lista de nodos con filtros", []),
 ("p", "La lista muestra cada nodo con su estado, cuándo se lo escuchó por última vez, señal, batería y distancia. Se puede filtrar por alcance, estado y función, y marcar <b>favoritos</b> con la estrella."),
 ("h3", "Ficha de nodo"),
 ("fig", "a04_ficha_nodo", "Ficha completa de un nodo", []),
 ("p", "Tocando el nombre de un nodo (en la lista, en un mensaje o en el mapa) se abre su ficha, con:"),
 ("ul", ["Identificador, modelo, función y cuándo se lo escuchó.",
         "Cómo llega: directo por radio, por cuántos saltos, o por MQTT; y qué nodo lo retransmitió.",
         "Señal, batería, uso del canal y sensores de ambiente.",
         "<b>Gráficos</b> de cómo fueron variando el SNR, el RSSI, la batería y la tensión.",
         "<b>Vecinos</b> que informa escuchar y los que dicen escucharlo a él.",
         "<b>Rutas medidas</b>: los últimos traceroute, ida y vuelta.",
         "Acciones: mensaje directo, trazar ruta, pedir posición, ver en el mapa, cómo llegar y telemetría."]),
 ("note", "<b>Los cortes de los gráficos.</b> Cada gráfico de la ficha lleva debajo el m\u00ednimo, el m\u00e1ximo y el per\u00edodo que abarca. Si el nodo estuvo un rato largo sin informar, el tramo se dibuja <b>punteado y apagado</b> en vez de una l\u00ednea llena: ah\u00ed no hubo mediciones. Conviene tenerlo en cuenta al mirar bater\u00eda o se\u00f1al, porque un salto punteado es falta de datos y no una ca\u00edda real."),
)

ch("Mapa",
 ("fig", "a05_mapa", "Mapa con los nodos (sin capa de internet)", []),
 ("ul", ["Se mueve arrastrando con un dedo.",
         "Se acerca y aleja <b>pellizcando</b>, con <b>doble toque</b> o con los botones <b>+</b> y <b>−</b>.",
         "El botón <b>◎</b> encuadra todos los nodos.",
         "<b>Capas</b> elige el mapa base y las superposiciones; arranca cerrado para dejar la pantalla libre.",
         "Tocando un nodo se abre su recuadro con posición, altura, saltos, distancia y botones para ir a Google Maps o abrir la ficha."]),
 ("h3", "Mapas para usar sin señal"),
 ("p", "Lo que mirás con Internet se guarda solo. Para tener una zona completa antes de salir, usá <b>Capas → ⬇ Guardar zona para usar sin conexión…</b>:"),
 ("steps", ["Centrá el mapa en el lugar y elegí en Capas el mapa base que querés guardar.",
            "Poné un nombre, el <b>radio</b> en kilómetros y los <b>zoom</b> mínimo y máximo. Guía: 12 = ciudad entera, 14 = barrios, 16 = calles, 17-18 = casas.",
            "Mirá la estimación de teselas y megabytes antes de descargar: cada nivel más de zoom multiplica por cuatro.",
            "Tocá <b>Descargar</b>. La barra muestra el avance y se puede cancelar. La zona queda en la lista de <b>Zonas guardadas</b>."]),
 ("warn", "Descargá solo lo que vayas a necesitar y respetá las condiciones de uso de cada proveedor de mapas. Algunos no permiten guardar; en ese caso la descarga te informa cuántas teselas fallaron."),
)

ch("Topología de la red",
 ("fig", "a06_topologia", "Diagrama de la red con enlaces medidos y rutas inferidas", []),
 ("p", "Muestra qué nodos se escuchan directamente, qué rutas se conocen y cuáles dependen de repetidores. Lo importante es que <b>separa lo medido de lo supuesto</b>:"),
 ("ul", ["<b>Línea llena verde:</b> enlace directo observado, con su SNR.",
         "<b>Línea llena azul:</b> informado por el módulo de vecinos.",
         "<b>Línea llena violeta:</b> medido con traceroute.",
         "<b>Línea punteada naranja:</b> ruta <b>inferida</b>, no confirmada. El portal nunca afirma que hay un enlace directo si los datos no lo demuestran.",
         "Tocando un enlace se ven RSSI, SNR, saltos y qué tan vieja es la medición."]),
 ("tip", "Para confirmar un tramo punteado, abrí la ficha de ese nodo y tocá <b>Trazar ruta</b>."),
)

ch("GPS del celular",
 ("fig", "a09_gps", "Ajustes del GPS del celular", []),
 ("p", "Si tu nodo no tiene GPS, la app le puede pasar la ubicación del teléfono. El nodo la comparte con la red como si fuera suya y aparece en el mapa de todos."),
 ("steps", ["Entrá en <b>Ajustes → GPS del celular</b>.",
            "Activá <b>Compartir mi ubicación con el nodo</b> y aceptá el permiso de ubicación.",
            "Elegí cada cuánto se envía (por defecto, como máximo cada 60 segundos), cuánto te tenés que mover para que se reenvíe (25 m) y cada cuánto se reenvía aunque estés quieto (15 minutos).",
            "En <b>Estado ahora</b> ves la última ubicación, su precisión y la que ya tiene el nodo. <b>Enviar posición</b> la manda en el momento."]),
 ("warn", "Si el nodo tiene <b>GPS propio encendido</b> o una <b>posición fija</b> configurada, va a seguir usando la suya. Para usar la del celular, en Configuración del dispositivo → Posición poné el GPS en «Desactivado» o «No presente» y desactivá la posición fija."),
 ("note", "Sigue enviando con la pantalla apagada mientras la app esté abierta. No bajes el intervalo de más: cada envío ocupa aire de la red, y 60 segundos con 25 metros alcanza de sobra para seguimiento a pie o en vehículo."),
)

ch("Canales y código QR",
 ("p", "Los canales son los grupos de la red. Comparten una clave: solo quien la tiene puede leer y escribir en ese canal. Se configuran en <b>Configuración de radio → Canales</b>."),
 ("h3", "Compartir tus canales"),
 ("ul", ["<b>▣ Mostrar código QR</b> arma un código con todos tus canales y la configuración de radio. Otro celular lo escanea y queda en la misma red.",
         "<b>Guardar imagen</b> lo baja como PNG para imprimirlo o mandarlo.",
         "<b>Copiar enlace</b> hace lo mismo en texto.",
         "El código es compatible con las demás aplicaciones LoRa Mesh."]),
 ("h3", "Entrar a la red de otro"),
 ("ul", ["<b>📷 Escanear QR</b> abre la cámara trasera. Apuntá al código y la app pregunta si reemplaza los canales del nodo.",
         "Si no hay cámara o el código está en una foto, usá <b>Elegir una foto del QR…</b>.",
         "También podés pegar el enlace y tocar <b>Importar</b>."]),
 ("warn", "El código QR y el enlace llevan las <b>claves</b> de los canales: cualquiera que los vea puede leer y escribir en ellos. Mostralos solo a gente de confianza."),
)

ch("Internet y MQTT desde el celular",
 ("fig", "a11_mqtt", "Ajustes de Internet y servidores MQTT", []),
 ("p", "Sin Internet la red LoRa funciona igual: la radio no depende de nada más. Con Internet, el portal puede además mandar y recibir por servidores <b>MQTT</b>, que alcanzan a nodos que están fuera del alcance de la radio."),
 ("ul", ["Se pueden configurar hasta seis servidores y <b>activar solo los que quieras</b>.",
         "Al enviar, el mensaje sale por el <b>primer servidor disponible</b>; no se manda repetido por todos, salvo que actives el modo redundante.",
         "La app trae un <b>puente integrado</b>, así que también llega a servidores que solo ofrecen TCP, como el oficial de la red. En la computadora eso requiere instalar Python; en el celular no hace falta nada.",
         "Si no hay Internet, los mensajes quedan en cola hasta una hora y salen solos cuando vuelve."]),
)

ch("Emergencias y libro de guardia",
 ("h3", "Botón de EMERGENCIAS"),
 ("p", "El botón rojo arma una alerta y la manda <b>a todos los canales activos</b>. Podés incluir teléfono, país, frecuencia y coordenada. Los mensajes que llegan empezando con 🚨, SOS, EMERGENCIA, PÁNICO o ALERTA se reconocen como alerta: el nodo parpadea en rojo en el mapa, suena el tono de pánico y aparece una barra arriba hasta que la marcás como atendida."),
 ("h3", "Novedades y guardia"),
 ("fig", "a12_guardia", "Libro de guardia en el celular", []),
 ("p", "Reúne los mensajes y los hechos importantes (nodos caídos, baterías bajas, alertas) con filtro por rango de horas. Se exporta a <b>PDF</b> o <b>Excel</b> desde el propio teléfono."),
 ("h3", "Dónde quedan los archivos"),
 ("p", "Todo lo que exportás se guarda en <b>Descargas/OPEN SOURCE PARIZ</b> y la app te ofrece abrirlo o compartirlo enseguida. <b>Imprimir / PDF</b> abre el servicio de impresión de Android, donde podés elegir <b>Guardar como PDF</b>."),
)

ch("Si el teléfono es viejo",
 ("p", "La aplicación usa el visor web que trae Android (<i>Android System WebView</i>) para mostrar el portal. Ese visor se actualiza solo desde Google Play, aparte del sistema: por eso un teléfono con Android 7 u 8 bien actualizado anda sin problemas, y uno más nuevo pero sin actualizar puede fallar."),
 ("ul", ["La aplicación pide <b>Android 7.0 o más nuevo</b>.",
         "Si al abrirla queda <b>una pantalla en blanco</b>, esperá unos segundos: aparece un cartel que explica qué pasa y qué actualizar.",
         "Para arreglarlo: Google Play → buscar <b>Android System WebView</b> → <i>Actualizar</i>; hacé lo mismo con <b>Chrome</b>. Después cerrá la aplicación del todo y volvé a abrirla."]),
 ("note", "<b>Conectarse por WiFi anda en cualquier lado.</b> La aplicación le pide la red al teléfono, no al visor web, así que buscar el nodo y hablarle por WiFi funciona incluso en teléfonos donde el visor es viejo."),
)

ch("Solución de problemas",
 ("table", ["Problema", "Qué probar"], [
   ["No encuentra el nodo por Bluetooth.", "Revisá que el Bluetooth del teléfono esté encendido, que la app tenga <b>Dispositivos cercanos</b> (o <b>Ubicación</b> en Android 11 o anterior, con la ubicación activada) y que el nodo no esté conectado a otro celular. Probá <b>Mostrar todos</b>."],
   ["Pide un PIN que no sé.", "Es el que muestra la pantalla del nodo. Sin pantalla, suele ser <b>123456</b>. Si ya estaba emparejado y falla, borralo en los ajustes de Bluetooth del teléfono y emparejá de nuevo."],
   ["Conecté el cable y no pasa nada.", "Tiene que ser un cable <b>de datos</b> y un adaptador <b>OTG</b>. Abrí la app y tocá <b>USB (cable)</b>. Si Android preguntó por otra app, desenchufá y volvé a enchufar."],
   ["Por WiFi no encuentra el nodo.", "En <b>Redes a revisar</b> van los <b>tres primeros números</b> de tu red (192.168.1), no la dirección completa. Si escribís una dirección entera, la app te ofrece un botón para revisar la red completa."],
   ["Lo encuentra pero no conecta.", "Tocá <b>Probar conexión</b>: el mensaje te dice si no contesta nadie, si contesta pero no deja que el portal le hable, o si es un problema de certificado."],
   ["Al abrir la aplicación queda una pantalla en blanco.", "El visor web del teléfono es demasiado viejo. Actualizá <b>Android System WebView</b> y <b>Chrome</b> desde Google Play y volvé a abrirla."],
   ["Se corta la conexión con la pantalla apagada.", "Ajustes del teléfono → Apps → OPEN SOURCE PARIZ → <b>Batería → Sin restricciones</b>. Y no cierres la app desde la lista de recientes."],
   ["No llegan los avisos.", "Revisá el permiso de <b>Notificaciones</b>, que estén activados en Ajustes → Sonidos y notificaciones, y que el canal no esté silenciado."],
   ["El nodo no toma la ubicación del celular.", "El nodo tiene GPS propio o posición fija: desactivalos en Configuración del dispositivo → Posición."],
   ["El escáner QR no abre la cámara.", "Aceptá el permiso de <b>Cámara</b>, o usá <b>Elegir una foto del QR…</b>."],
   ["Se conecta pero no llegan mensajes.", "Verificá que la <b>región</b> y el <b>preset</b> coincidan con los de los demás nodos y que haya otro nodo al alcance. Mirá el <b>Módulo de consola</b> para ver el tráfico de radio."],
   ["Play Protect no me deja instalar.", "Más detalles → <b>Instalar de todas formas</b>. Aparece porque la app no está publicada en la tienda."],
   ["Quiero volver a empezar de cero.", "Ajustes → Administración y respaldo → Datos del portal. Ahí se borra lo guardado en el teléfono sin tocar el nodo."]]),
)

ch("Preguntas frecuentes",
 ("ul", ["<b>¿Necesito Internet?</b> No. La radio LoRa funciona sola. Internet solo suma los servidores MQTT y los mapas en línea.",
         "<b>¿Necesito la computadora?</b> No. La app hace todo lo que hace el portal de la PC, incluido el puente MQTT.",
         "<b>¿Mis mensajes salen a algún servidor?</b> Solo si activás MQTT. Sin eso, todo queda entre tu teléfono y el nodo.",
         "<b>¿Dónde se guardan mis datos?</b> En el propio teléfono. No hay cuenta ni servidor propio.",
         "<b>¿Puedo usar la app y la PC al mismo tiempo?</b> Sí, pero el nodo atiende una conexión Bluetooth por vez. Por WiFi sí admite varias.",
         "<b>¿Funciona con cualquier nodo?</b> Con módulos de firmware 2.x. Se probó con Heltec V3 y firmware 2.8.",
         "<b>¿Es software libre?</b> Sí. Incluye componentes bajo licencia GPL-3.0 y el código fuente se entrega junto con la aplicación."]),
 ("note", "Esta aplicación no está asociada ni respaldada por ningún organismo. Es una herramienta propia, de uso libre, entregada tal cual."),
)
